<script setup>
import { confirmAction } from '@/lib/confirm-action.js';
import{ref,watch,onMounted}from'vue';import{api}from'@/services/api.js';import{useRoute}from'vue-router';import{useLearning}from'@/store.js';
const route=useRoute(),store=useLearning();import{RefreshCw,Users}from'@/components/app/icons.js';
const rooms=ref([]),knowledge=ref([]),papers=ref([]),plans=ref([]),room=ref(''),kid=ref(''),students=ref([]),selection=ref({}),versions=ref({}),active=ref(null),error=ref(''),notice=ref(''),busy=ref(false),labels=['补基础','巩固','拓展','证据不足'];const editing=ref(false);let generation=0;
const call=(path,method='GET',body)=>api.request('/groups'+path,{method,...(body?{body:JSON.stringify(body)}:{})});
async function load(){try{plans.value=await call('');if(active.value){const fresh=plans.value.find(p=>p.id===active.value.id);if(fresh)active.value=fresh}}catch(e){error.value=e.message}}
onMounted(async()=>{try{[rooms.value,knowledge.value,papers.value]=await Promise.all([api.request('/teaching/classes'),api.request('/curriculum/knowledge'),api.request('/exams/papers')]);room.value=rooms.value.find(c=>c.id===String(route.query.class||store.currentClassId))?.id||rooms.value[0]?.id||'';kid.value=knowledge.value[0]?.id||'';await load()}catch(e){error.value=e.message}});
watch(()=>route.query.class,id=>{if(id&&rooms.value.some(c=>c.id===String(id)))room.value=String(id)});
watch([room,kid],()=>{generation++;students.value=[];selection.value={};active.value=null;notice.value=''});
async function suggest(){const g=++generation;busy.value=true;try{const r=await call('/suggestions?classId='+encodeURIComponent(room.value)+'&knowledgeId='+encodeURIComponent(kid.value));if(g!==generation)return;students.value=r.students;selection.value=Object.fromEntries(r.students.map(s=>[s.studentId,s.suggestion]));notice.value='已读取建议';error.value=''}catch(e){if(g===generation)error.value=e.message}finally{busy.value=false}}
function open(plan){editing.value=true;active.value=plan;room.value=plan.classId;kid.value=plan.knowledgeId;setTimeout(()=>{active.value=plan;students.value=Object.values(plan.evidence);selection.value=Object.fromEntries(plan.groups.flatMap(g=>g.studentIds.map(id=>[id,g.label])));versions.value=Object.fromEntries(plan.groups.map(g=>[g.label,g.versionId]))},0)}
async function save(){busy.value=true;error.value='';try{const groups=labels.map(label=>({label,studentIds:students.value.filter(s=>selection.value[s.studentId]===label).map(s=>s.studentId),versionId:versions.value[label]})).filter(g=>g.studentIds.length);const r=await call(active.value?'/'+active.value.id:'',active.value?'PUT':'POST',{classId:room.value,knowledgeId:kid.value,groups,...(active.value?{revision:active.value.revision}:{})});active.value=r;await load();notice.value='安排已保存，尚未发布。'}catch(e){error.value=e.message}finally{busy.value=false}}
async function publish(){if(!await confirmAction('确认成员和不同练习？发布后各组只会收到自己的任务，历史安排保留。'))return;busy.value=true;error.value='';try{active.value=await call('/'+active.value.id+'/publish','POST',{revision:active.value.revision,confirmed:true});await load();notice.value='分层练习已发布。'}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><PageHeading title="分层教学"><AppButton @click="editing=true;active=null;students=[];selection={};versions={}">新建安排</AppButton><AppButton variant="ghost" @click="load" aria-label="刷新教学安排"><RefreshCw :size="16"/></AppButton></PageHeading><AppAlert type="error" v-if="error" role="alert" class="form-error">{{error}}</AppAlert><AppAlert type="success" v-if="notice" role="status" class="exam-notice">{{notice}}</AppAlert><section v-if="editing" class="ops-group-editor"><div class="ops-row-title"><h2>{{active?'教学安排':'新建安排'}}</h2><AppButton variant="ghost" @click="editing=false">返回列表</AppButton></div><Surface><div class="teaching-form-row"><label>班级<NativeSelect v-model="room"><option v-for="c in rooms" :key="c.id" :value="c.id">{{c.name}}</option></NativeSelect></label><label>知识点<NativeSelect v-model="kid"><option v-for="k in knowledge" :key="k.id" :value="k.id">{{k.name}}</option></NativeSelect></label><AppButton :disabled="busy||!room||!kid" @click="suggest"><Users :size="16"/>读取分组建议</AppButton></div></Surface><div v-if="students.length" class="teaching-group-layout"><Surface><AppEmpty v-if="!students.length" class="empty-state">选择班级和知识点，读取实际作答依据</AppEmpty><div v-else class="table-container"><AppTable class="live-answer-table"><thead><tr><th>学生</th><th>依据</th><th>本次安排</th></tr></thead><tbody><tr v-for="s in students" :key="s.studentId"><td>{{s.name}}</td><td><span>{{s.state.statusLabel}}</span><AppDisclosure><template #title>{{s.evidenceIds.length}} 条原始证据</template><RouteButton :route="'memory?studentId='+s.studentId+'&classId='+room" secondary>查看原始记录</RouteButton><InfoTip label="证据编号">{{s.evidenceIds.join('、')}}</InfoTip></AppDisclosure></td><td><NativeSelect v-model="selection[s.studentId]" :disabled="active?.published" :aria-label="s.name+'本次分组'"><option v-for="label in labels" :key="label">{{label}}</option></NativeSelect></td></tr></tbody></AppTable></div></Surface><Surface><h2>分配练习</h2><label v-for="label in labels" :key="label" class="teaching-label">{{label}}<NativeSelect v-model="versions[label]" :disabled="active?.published"><option :value="undefined">选择已审核试卷</option><template v-for="p in papers" :key="p.id"><option v-for="v in p.versions" :key="v.id" :value="v.id">{{p.draft.title}} 　 v{{v.number}}</option></template></NativeSelect></label><div class="exam-toolbar"><AppButton :disabled="busy||!students.length||active?.published" @click="save">保存安排</AppButton><AppButton variant="outline" :disabled="busy||!active||active.published" @click="publish">确认发布</AppButton></div></Surface></div><Surface v-if="active?.published" class="teaching-history"><h2>实际完成情况</h2><Surface data-ui="card" role="article" v-for="t in active.tasks" :key="t.id"><h3>{{t.title}}</h3><dl class="focus-question-stats"><div><dt>已分配</dt><dd>{{t.assigned}}</dd></div><div><dt>已提交</dt><dd>{{t.submitted}}</dd></div><div><dt>独立答对<InfoTip label="统计范围">仅计本次任务中有独立正确记录的学生，不代表已经掌握。</InfoTip></dt><dd>{{t.independentCorrectStudents}}</dd></div></dl><RouteButton :route="'insights?task='+t.id" secondary>查看实际作答</RouteButton></Surface></Surface></section><Surface v-if="!editing" class="teaching-history"><h2>教学安排</h2><AppEmpty v-if="!plans.length" class="empty-state"><Users :size="26"/><h3>还没有教学安排</h3><AppButton @click="editing=true;active=null;students=[];selection={};versions={}">新建安排</AppButton></AppEmpty><AppButton variant="ghost" data-layout="row" type="button" v-for="p in plans" :key="p.id" class="exam-paper-link" @click="open(p)"><strong>{{knowledge.find(k=>k.id===p.knowledgeId)?.name}}</strong><span>{{p.published?'已发布':'草稿'}} 　 {{p.groups.length}}组</span></AppButton></Surface></template>
